insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('NL:civil-engineer','2026-08-12',null,19.12,38772,15,0,0,0,8,6,0,3,5,37,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2142 Civil Engineers; Dutch civiel ingenieur scope.','shortage_note','UWV identifies civil engineering and construction engineering among higher-education technical fields with good job opportunities driven by infrastructure and housing demand; 15/20.','visa_basis','The Netherlands has no Civil Engineer-specific immigration fast track. Highly Skilled Migrant access depends on a recognised IND sponsor, market-rate pay and the applicable salary criterion; 3/10.','salary_method','Studiekeuze123 Civiele Techniek HBO bachelor estimated graduate starting salary EUR 3,231/month, annualised to EUR 38,772; hourly proxy EUR 19.12 using the published 39-hour graduate workweek; 6/10.','entry_basis','Degree-level professional entry is typical; HBO bachelor and WO routes are available but are less direct than short vocational pathways; 8/15.','entry_burden_basis','No universal statutory Dutch Civil Engineer occupational register; 5/5.'),'2026-08-12'),
('NL:mechanical-engineer','2026-08-12',null,18.54,37596,15,0,0,0,8,6,0,3,5,37,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2144 Mechanical Engineers; Dutch werktuigbouwkundig ingenieur scope.','shortage_note','UWV identifies mechanical engineering among engineering disciplines with good job prospects and links industrial and energy-transition work to continuing demand for mechanical specialists; 15/20.','visa_basis','No Mechanical Engineer-specific Dutch immigration fast track; recognised-sponsor and salary rules apply to the Highly Skilled Migrant route; 3/10.','salary_method','Studiekeuze123 Werktuigbouwkunde HBO bachelor estimated graduate starting salary EUR 3,133/month, annualised to EUR 37,596; hourly proxy EUR 18.54 using the published 39-hour workweek; 6/10.','entry_basis','HBO/WO degree-level professional route; 8/15.','entry_burden_basis','No universal statutory Dutch Mechanical Engineer register; 5/5.'),'2026-08-12'),
('NL:electrical-engineer','2026-08-12',null,19.35,38244,20,0,0,0,8,6,0,3,5,42,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2151 Electrical Engineers; Dutch elektrotechnisch ingenieur scope.','shortage_note','UWV Q1 2026 explicitly names electrical engineers among occupations with major shortages, while the higher-education outlook also identifies electrical engineering as a strong technical field; 20/20.','visa_basis','No Electrical Engineer-specific Dutch immigration fast track. Highly Skilled Migrant eligibility remains employer-, sponsor-, salary- and market-rate dependent; 3/10.','salary_method','Studiekeuze123 Elektrotechniek HBO bachelor estimated graduate starting salary EUR 3,187/month, annualised to EUR 38,244; hourly proxy EUR 19.35 using the published 38-hour workweek; 6/10.','entry_basis','HBO/WO degree-level professional route; 8/15.','entry_burden_basis','No universal statutory Dutch Electrical Engineer register; role-specific safety requirements do not create a single national professional licence; 5/5.'),'2026-08-12'),
('NL:manufacturing-engineer','2026-08-12',null,19.20,38940,15,0,0,0,8,6,0,3,5,37,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2141 Industrial and Production Engineers — manufacturing engineering scope focused on production systems, manufacturing processes and automation.','shortage_note','UWV reports persistent engineering demand in Dutch industry and identifies process technology, mechanical engineering and electrical engineering as key higher-education capabilities for industrial sustainability; 15/20.','visa_basis','No Manufacturing Engineer-specific migration fast track; Highly Skilled Migrant rules remain sponsor- and salary-dependent; 3/10.','salary_method','Studiekeuze123 Technische Bedrijfskunde HBO bachelor estimated graduate starting salary EUR 3,245/month, annualised to EUR 38,940; hourly proxy EUR 19.20 using the published 39-hour workweek; used transparently as a manufacturing/industrial early-career proxy; 6/10.','entry_basis','HBO Engineering, Mechanical Engineering or Technical Business routes are typical; 8/15.','entry_burden_basis','No universal statutory Manufacturing Engineer register; 5/5.'),'2026-08-12'),
('NL:industrial-engineer','2026-08-12',null,19.20,38940,15,0,0,0,8,6,0,3,5,37,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2141 Industrial and Production Engineers — industrial/process optimisation scope focused on productivity, operations, quality and integrated systems.','shortage_note','UWV continues to identify engineering and higher technical skills as promising and Dutch industrial transition requires process, mechanical, electrical and digital expertise; 15/20.','visa_basis','No Industrial Engineer-specific migration fast track; recognised-sponsor and salary criteria remain decisive for Highly Skilled Migrant access; 3/10.','salary_method','Studiekeuze123 Technische Bedrijfskunde HBO bachelor estimated graduate starting salary EUR 3,245/month, annualised to EUR 38,940; hourly proxy EUR 19.20 using the published 39-hour workweek; 6/10.','entry_basis','Technical Business/Engineering degree-level route; 8/15.','entry_burden_basis','No universal statutory Dutch Industrial Engineer register; 5/5.'),'2026-08-12'),
('NL:chemical-engineer','2026-08-12',null,18.41,36384,10,0,0,0,8,6,0,3,5,32,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2145 Chemical Engineers; Dutch chemisch ingenieur/process-engineering scope.','shortage_note','UWV identifies process technology as a key knowledge domain for industrial sustainability and reports continuing technical shortages, but the reviewed evidence does not establish the same direct occupation-specific shortage as Electrical Engineer; 10/20.','visa_basis','No Chemical Engineer-specific Dutch immigration fast track; 3/10.','salary_method','Studiekeuze123 Chemische Technologie HBO bachelor estimated graduate starting salary EUR 3,032/month, annualised to EUR 36,384; hourly proxy EUR 18.41 using the published 38-hour workweek; 6/10.','entry_basis','HBO/WO chemistry or chemical/process engineering degree route; 8/15.','entry_burden_basis','No universal statutory Dutch Chemical Engineer register; regulated process-safety responsibilities are position-specific; 5/5.'),'2026-08-12'),
('NL:environmental-engineer','2026-08-12',null,18.92,35424,15,0,0,0,8,6,0,3,5,37,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2143 Environmental Engineers; Dutch environmental engineering scope covering sustainable systems, remediation, water and environmental technology.','shortage_note','UWV higher-education guidance identifies sustainability, environment and energy-management specialists as promising and links climate measures to continuing technical demand; 15/20.','visa_basis','No Environmental Engineer-specific Dutch immigration fast track; 3/10.','salary_method','Studiekeuze123 Milieukunde HBO bachelor estimated graduate starting salary EUR 2,952/month, annualised to EUR 35,424; hourly proxy EUR 18.92 using the published 36-hour workweek; used as a conservative environmental early-career proxy; 6/10.','entry_basis','Degree-level environmental/engineering route; 8/15.','entry_burden_basis','No universal statutory Dutch Environmental Engineer register; 5/5.'),'2026-08-12'),
('NL:engineering-technician','2026-08-12',null,18.11,36732,15,0,0,0,12,6,0,3,5,41,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 3119 Physical and Engineering Science Technicians Not Elsewhere Classified used as a broad cross-discipline Engineering Technician proxy.','shortage_note','UWV reports persistent shortages across technical occupations and finds many technician and engineering roles structurally promising; broad technician demand earns 15/20 without inheriting Electrical Engineer maximum credit.','visa_basis','No generic Engineering Technician-specific immigration fast track; standard work routes depend on employer, permit and salary circumstances; 3/10.','salary_method','Studiekeuze123 Engineering HBO Associate Degree estimated graduate starting salary EUR 3,061/month, annualised to EUR 36,732; hourly proxy EUR 18.11 using the published 39-hour workweek; 6/10.','entry_basis','Two-year HBO Associate Degree Engineering provides a comparatively accessible bridge from MBO level 4 to engineering work and bachelor progression; 12/15.','entry_burden_basis','No universal statutory Dutch Engineering Technician register; 5/5.'),'2026-08-12')
